// Generated at build time by scripts/build-views.mjs from @fontsource-variable/geist and
// @fontsource-variable/geist-mono: one entry per @font-face, the woff2 file as base64.
declare module 'virtual:taxpresso-fonts' {
  const fonts: { family: string; style: string; weight: string; range: string; data: string }[];
  export default fonts;
}
